/*
 PLAN
 1) Composition: 5-card filmstrip along x at 1.85 pitch, strip yawed -18deg receding right; focused card at x=0 faces camera; graded backdrop plane 7x6 at z=-2.5; headline top-left, body bottom-left, caption under focused card; contact shadow plane under strip.
 2) Light rig (rig-dusk-editorial): warm key dir #ffc890 2.8 from [3,0.9,1.2]; fill point #b9a68e 3 at [-2.4,0.6,1.8]; cool rim dir #f2f4f6 1.7 from [-1.8,2.8,-2]; ambient floor 0.09.
 3) Materials: photo plates MeshStandardNodeMaterial map + tint variants, roughness 0.55 metalness 0.2; machined ink bevel frames physical clearcoat 0.15; accent underline emissive #ff2a38 at 1.3.
 4) Motion: rise-in entrance power3.out 0.7s with weighted settle 1.04->1.0; parallax-scroll primitive intensity 0.5 with UV counter-shift; idle single-axis breathing <=2%; snap settle 0.9s power4.out.
 5) Focal element: the focused center card (brightest, face-on, red underline bar) — everything else graded below it.
*/
import { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, DirectionalLight, PointLight, AmbientLight, Color, MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, float, uniform, texture as tslTexture, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'filmstrip-carousel';

  const COLORS = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const spec = config.intent?.visualSpec ?? {};
  const c = spec.colors ?? {};
  const bgHex = c.background ?? COLORS.background;
  const surfaceHex = c.surface ?? COLORS.surface;
  const inkHex = c.ink ?? COLORS.ink;
  const paperHex = c.paper ?? COLORS.paper;
  const accentHex = c.accent ?? COLORS.accent;
  const gradientStops = c.gradientStops ?? [{ at: 0, hex: bgHex }, { at: 1, hex: '#12121a' }];

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---------- backdropStage: graded gradient plane, never void ----------
  function backdropStage() {
    const geo = new PlaneGeometry(7, 6);
    const mat = new MeshBasicNodeMaterial();
    const bottom = tslColor(new Color(gradientStops[0].hex));
    const top = tslColor(new Color(gradientStops[gradientStops.length - 1].hex));
    const surfaceGlow = tslColor(new Color(surfaceHex));
    const v = uv();
    // vertical gradient + faint radial lift behind the focused card so the stage reads as lit atmosphere
    const grad = mix(bottom, top, smoothstep(0.0, 1.0, v.y));
    const d = v.sub(vec2(0.5, 0.45)).length();
    const lift = smoothstep(0.55, 0.0, d).mul(0.35);
    mat.colorNode = vec4(mix(grad, surfaceGlow.mul(1.6), lift), 1.0);
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, 0, -2.5);
    disposables.push(geo, mat);
    return mesh;
  }
  root.add(backdropStage());

  // ---------- lightRig: rig-dusk-editorial ----------
  function lightRig() {
    const g = new Group();
    const key = new DirectionalLight(new Color('#ffc890'), 1.4); // capped for white/paper reads
    key.position.set(3, 0.9, 1.2);
    key.target.position.set(0, 0.4, 0);
    g.add(key, key.target);
    const fill = new PointLight(new Color('#b9a68e'), 1.5, 9, 2);
    fill.position.set(-2.4, 0.6, 1.8);
    g.add(fill);
    const rim = new DirectionalLight(new Color('#f2f4f6'), 1.2);
    rim.position.set(-1.8, 2.8, -2);
    rim.target.position.set(0, 0.6, 0);
    g.add(rim, rim.target);
    const amb = new AmbientLight(new Color(surfaceHex), 0.09);
    g.add(amb);
    return g;
  }
  root.add(lightRig());

  // ---------- filmstripCards ----------
  const strip = new Group();
  strip.name = 'filmstrip-strip';
  strip.rotation.y = -18 * Math.PI / 180;
  strip.position.set(0.2, -0.15, 0);
  root.add(strip);

  const CARD_W = 1.6, CARD_H = 1.0, PITCH = 1.85, BEVEL = 0.025;
  const captions = ['NA-01 MERIDIAN', 'NA-02 NOCTURNE', 'NA-03 SIGNAL', 'NA-04 VANTAGE', 'NA-05 ARCHIVE'];
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const captionItems = textItems.filter((t) => t.role === 'caption');
  const headlineItem = textItems.find((t) => t.role === 'headline');
  const bodyItem = textItems.find((t) => t.role === 'body');

  // Distinct plate variants: per-card TSL grade (hue/contrast offsets) on the shared base photo
  // + per-card UV window offsets so each plate crops a DIFFERENT region — no repeated subject echo.
  const uvOffsets = [vec2(0.0, 0.0), vec2(0.22, 0.05), vec2(0.05, 0.28), vec2(0.3, 0.3), vec2(0.15, 0.15)];
  const grades = [
    { tint: vec3(1.0, 1.0, 1.0), lift: 0.0 },   // neutral (focused)
    { tint: vec3(0.85, 0.9, 1.05), lift: -0.04 }, // nocturne cool
    { tint: vec3(1.08, 0.92, 0.9), lift: 0.02 },  // signal warm
    { tint: vec3(0.95, 1.02, 0.95), lift: -0.02 },// vantage green-neutral
    { tint: vec3(0.9, 0.88, 0.86), lift: -0.06 }, // archive faded sepia
  ];

  const cardMats = [];
  const opacityUniforms = [];
  const uvShiftUniform = uniform(0); // driven by parallax scroll for internal UV counter-shift

  const sharedTexPromise = ctx.textureLoader.loadTexture(config.imageUrl ?? '/prism-mock/home/nodes/parallax-stack.png');

  const cards = [];
  for (let i = 0; i < 5; i++) {
    const card = new Group();
    const x = (i - 2) * PITCH;
    card.position.x = x;
    const focused = i === 2;

    // photo plate
    const plateGeo = new PlaneGeometry(CARD_W - BEVEL * 2, CARD_H - BEVEL * 2);
    const plateMat = new MeshStandardNodeMaterial({ roughness: 0.55, metalness: 0.2, transparent: true });
    const op = uniform(focused ? 1.0 : Math.max(0.55, 1.0 - Math.abs(i - 2) * 0.225));
    opacityUniforms.push(op);
    plateMat.opacityNode = op;
    const g = grades[i];
    sharedTexPromise.then((tex) => {
      const cropped = uv().mul(0.66).add(uvOffsets[i]).add(vec2(uvShiftUniform.mul(0.04), 0));
      const sample = tslTexture(tex, cropped);
      plateMat.colorNode = vec3(sample.r, sample.g, sample.b).mul(g.tint).add(g.lift);
      plateMat.needsUpdate = true;
    });
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0.021;
    card.add(plate);
    cardMats.push(plateMat);
    disposables.push(plateGeo, plateMat);

    // machined ink bevel frame
    const frameGeo = new BoxGeometry(CARD_W + BEVEL * 2, CARD_H + BEVEL * 2, 0.04);
    const frameMat = new MeshPhysicalNodeMaterial({
      color: new Color(inkHex),
      roughness: 0.5,
      metalness: 0.55,
      clearcoat: 0.15,
    });
    const frame = new Mesh(frameGeo, frameMat);
    card.add(frame);
    disposables.push(frameGeo, frameMat);

    if (focused) {
      // counter-rotate to face camera dead-on
      card.rotation.y = 18 * Math.PI / 180;
      card.scale.setScalar(1.0);
      // accent underline bar
      const barGeo = new BoxGeometry(1.6, 0.035, 0.02);
      const barMat = new MeshBasicNodeMaterial();
      barMat.colorNode = tslColor(new Color(accentHex)).mul(1.3);
      const bar = new Mesh(barGeo, barMat);
      bar.position.set(0, -CARD_H / 2 - 0.125, 0.03);
      card.add(bar);
      disposables.push(barGeo, barMat);
    } else {
      card.scale.setScalar(0.92);
    }

    // caption below each card
    const capText = (captionItems[i]?.text) ?? captions[i];
    const cap = ctx.fontAtlas.createText(String(capText), {
      fontSize: 18,
      color: focused ? paperHex : '#8a8f98',
      align: 'center',
      letterSpacingPx: 1.4,
    });
    cap.position.set(0, -CARD_H / 2 - 0.25, 0.03);
    card.add(cap);

    cards.push(card);
    strip.add(card);
  }

  // ---------- contactShadow ----------
  function contactShadow() {
    const geo = new CircleGeometry(3.2, 48);
    const mat = new MeshBasicNodeMaterial({ transparent: true });
    const d = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    mat.colorNode = vec3(0.0, 0.0, 0.0);
    mat.opacityNode = smoothstep(1.0, 0.2, d).mul(0.5);
    const mesh = new Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(0.2, -0.95, -0.2);
    mesh.scale.set(1.3, 0.45, 1);
    disposables.push(geo, mat);
    return mesh;
  }
  root.add(contactShadow());

  // ---------- headlineText / bodyText ----------
  const headline = ctx.fontAtlas.createText(String(headlineItem?.text ?? 'The collection'), {
    fontSize: 68,
    color: paperHex,
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0.2);
  root.add(headline);

  const body = ctx.fontAtlas.createText(String(bodyItem?.text ?? 'Five calibres. One discipline.'), {
    fontSize: 26,
    color: '#b6bcc6',
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0.2);
  root.add(body);

  // ---------- entranceMotion ----------
  const intro = gsap.timeline();
  intro.from(headline.position, { y: headline.position.y - 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  intro.from(body.position, { y: body.position.y - 0.2, duration: 0.5, ease: 'power2.out' }, 0.15);
  cards.forEach((card, i) => {
    const targetScale = card.scale.x;
    intro.fromTo(card.scale,
      { x: targetScale * 0.9, y: targetScale * 0.9, z: targetScale * 0.9 },
      { x: targetScale * 1.04, y: targetScale * 1.04, z: targetScale * 1.04, duration: 0.5, ease: 'power3.out' },
      0.2 + i * 0.08);
    intro.to(card.scale,
      { x: targetScale, y: targetScale, z: targetScale, duration: 0.9, ease: 'power4.out' },
      0.7 + i * 0.08);
  });
  timelines.push(intro);

  // idle: ONE slow breathing on the focused card (<=2%)
  const idle = gsap.to(cards[2].scale, {
    x: 1.02, y: 1.02, z: 1.02,
    duration: 3.2, ease: 'sine.inOut', repeat: -1, yoyo: true, delay: 1.8,
  });
  timelines.push(idle);

  // ---------- primitives: parallax-scroll (config-driven, never inlined) ----------
  for (const prim of (config.cinematicPrimitives ?? [])) {
    const fn = ctx.primitives[prim.name];
    if (fn) {
      const handle = fn(strip, prim.params);
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------- scroll snap: weighted settle + UV counter-shift ----------
  let snapTween = null;
  root.userData.handlers = {
    scroll: (payload) => {
      const delta = (payload && typeof payload.delta === 'number') ? payload.delta : 0;
      uvShiftUniform.value = Math.max(-1, Math.min(1, uvShiftUniform.value - delta * 0.5));
    },
    scrollend: () => {
      // snap strip to nearest card pitch with weighted settle
      const snapped = Math.round(strip.position.x / PITCH) * PITCH + 0.2;
      if (snapTween) snapTween.kill();
      snapTween = gsap.timeline()
        .to(strip.position, { x: snapped * 1.04, duration: 0.35, ease: 'power2.out' })
        .to(strip.position, { x: snapped, duration: 0.9, ease: 'power4.out' });
      timelines.push(snapTween);
      gsap.to(uvShiftUniform, { value: 0, duration: 0.9, ease: 'power4.out' });
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t && t.kill && t.kill());
    if (snapTween) snapTween.kill();
    primitiveHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((r) => r && r.dispose && r.dispose());
    sharedTexPromise.then((tex) => tex && tex.dispose && tex.dispose()).catch(() => {});
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"headlineText / createNode","how":"fontAtlas headline at [-2.6,1.5]"},
{"id":"text.body.1","where":"bodyText / createNode","how":"fontAtlas body at [-2.6,-1.5]"},
{"id":"text.caption.2","where":"filmstripCards loop i=0","how":"caption under card 0"},
{"id":"text.caption.3","where":"filmstripCards loop i=1","how":"caption under card 1"},
{"id":"text.caption.4","where":"filmstripCards loop i=2","how":"caption under focused card"},
{"id":"text.caption.5","where":"filmstripCards loop i=3","how":"caption under card 3"},
{"id":"text.caption.6","where":"filmstripCards loop i=4","how":"caption under card 4"},
{"id":"color.background","where":"backdropStage","how":"gradient stop 0 base"},
{"id":"color.surface","where":"backdropStage","how":"radial lift glow color"},
{"id":"color.ink","where":"filmstripCards frameMat","how":"machined bevel frame color"},
{"id":"color.paper","where":"headlineText","how":"headline and focused caption color"},
{"id":"color.accent","where":"filmstripCards focused bar","how":"emissive underline bar 1.3"},
{"id":"color.gradient","where":"backdropStage","how":"vertical 2-stop TSL gradient"},
{"id":"effects.spec","where":"filmstripCards","how":"5 cards, 1.85 pitch, -18deg, focus, opacity falloff"},
{"id":"primitive.parallax-scroll","where":"primitives loop","how":"ctx.primitives applied to strip"}
]}
*/
